-- ==============================================================================
-- Flyway Migration V12: Question Bank & IndiaBix-Style MCQ Assessment Schema
-- Database: PostgreSQL 16 / H2 compatible
-- Project: SkillForge AI
-- ==============================================================================

-- 1. Question Bank Table
CREATE TABLE IF NOT EXISTS question_bank (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    category VARCHAR(100) NOT NULL, -- Aptitude, Technical, General
    topic VARCHAR(100) NOT NULL,    -- Quantitative Aptitude, Logical Reasoning, Java, React, SQL, etc.
    subtopic VARCHAR(100),
    difficulty VARCHAR(20) NOT NULL DEFAULT 'MEDIUM', -- EASY, MEDIUM, HARD
    question_text TEXT NOT NULL,
    option_a TEXT NOT NULL,
    option_b TEXT NOT NULL,
    option_c TEXT NOT NULL,
    option_d TEXT NOT NULL,
    correct_option INT NOT NULL DEFAULT 0, -- 0=A, 1=B, 2=C, 3=D
    explanation TEXT NOT NULL,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP
);

CREATE INDEX IF NOT EXISTS idx_qbank_category ON question_bank(category);
CREATE INDEX IF NOT EXISTS idx_qbank_topic ON question_bank(topic);
CREATE INDEX IF NOT EXISTS idx_qbank_difficulty ON question_bank(difficulty);

