INSERT INTO question_bank (id, category, topic, subtopic, difficulty, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES
('d1000000-0000-0000-0000-000000000001', 'Aptitude', 'Quantitative Aptitude', 'Percentages', 'EASY', 'A student scored 85 out of 100 in Math and 90 out of 120 in Science. What is the overall combined percentage?', '78.5%', '79.54%', '82.1%', '85.0%', 1, 'Total marks obtained = 85 + 90 = 175. Total maximum marks = 100 + 120 = 220. Combined Percentage = (175 / 220) * 100 = 79.54%.'),
('d1000000-0000-0000-0000-000000000002', 'Aptitude', 'Quantitative Aptitude', 'Profit & Loss', 'MEDIUM', 'A laptop is sold for $720 at a profit of 20%. What was the cost price of the laptop?', '$550', '$600', '$640', '$650', 1, 'Selling Price (SP) = Cost Price (CP) * 1.20. Therefore, CP = 720 / 1.20 = $600.'),
('d1000000-0000-0000-0000-000000000003', 'Aptitude', 'Quantitative Aptitude', 'Speed & Distance', 'MEDIUM', 'A train running at a speed of 60 km/h crosses a pole in 9 seconds. What is the length of the train in meters?', '120 m', '150 m', '180 m', '200 m', 1, 'Speed in m/s = 60 * (5/18) = 50/3 m/s. Distance = Speed * Time = (50/3) * 9 = 150 meters.'),
('d1000000-0000-0000-0000-000000000004', 'Aptitude', 'Quantitative Aptitude', 'Probability', 'HARD', 'Two fair dice are rolled simultaneously. What is the probability that the sum of the numbers is 8?', '5/36', '1/6', '7/36', '1/9', 0, 'Total outcomes = 6 * 6 = 36. Outcomes with sum 8 are (2,6), (3,5), (4,4), (5,3), (6,2) -> 5 outcomes. Probability = 5/36.'),
('d1000000-0000-0000-0000-000000000005', 'Aptitude', 'Quantitative Aptitude', 'Averages', 'EASY', 'The average score of 5 students in an assessment is 80. If a 6th student scores 98, what is the new average?', '82', '83', '84', '85', 1, 'Initial total score = 5 * 80 = 400. New total = 400 + 98 = 498. New average for 6 students = 498 / 6 = 83.');

