INSERT INTO question_bank (id, category, topic, subtopic, difficulty, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES
('d1000000-0000-0000-0000-000000000010', 'Aptitude', 'Logical Reasoning', 'Number Series', 'EASY', 'Find the next number in the sequence: 3, 7, 15, 31, 63, ?', '95', '127', '128', '131', 1, 'Each term is generated by (previous * 2) + 1. (63 * 2) + 1 = 127.'),
('d1000000-0000-0000-0000-000000000011', 'Aptitude', 'Logical Reasoning', 'Coding-Decoding', 'MEDIUM', 'If "PYTHON" is coded as "QZUIPO", how is "SPRING" coded in the same pattern?', 'TQSHOH', 'TQSIOH', 'RROHMFF', 'TQRJOH', 1, 'Pattern: Shift each letter forward by +1 in the alphabet (P->Q, Y->Z, T->U, H->I, O->P, N->O). S->T, P->Q, R->S, I->J, N->O, G->H -> TQSIOH.'),
('d1000000-0000-0000-0000-000000000012', 'Aptitude', 'Logical Reasoning', 'Syllogism', 'HARD', 'Statements: "All algorithms are functions. All functions are logic." Conclusions: I. All algorithms are logic. II. Some logic are functions.', 'Only I follows', 'Only II follows', 'Both I and II follow', 'Neither follows', 2, 'By transitive property: Algorithms ⊆ Functions ⊆ Logic. Therefore, All algorithms are logic (I) is True, and Some logic are functions (II) is True.'),
('d1000000-0000-0000-0000-000000000013', 'Aptitude', 'Logical Reasoning', 'Blood Relations', 'MEDIUM', 'Pointing to a photo, Sarah said, "His mother is the only daughter of my mother." How is Sarah related to the boy in the photo?', 'Sister', 'Mother', 'Aunt', 'Grandmother', 1, 'Sarah''s mother''s only daughter is Sarah herself. Therefore, Sarah is the boy''s mother.');

